/// Stacks two equally-sized vectors of f32 vertically into a two-row matrix.
fn vstack(a: Vec<f32>, b: Vec<f32>) -> Vec<Vec<f32>> {
    assert!(
        a.len() == b.len(),
        "Input vectors must have the same length"
    );
    vec![a, b]
}

/// Alias for `vstack`, produces the same two-row matrix.
fn make_outer(a: Vec<f32>, b: Vec<f32>) -> Vec<Vec<f32>> {
    vstack(a, b)
}

fn main() {
    let a = vec![1.0, 2.0, 3.0];
    let b = vec![4.0, 5.0, 6.0];

    let stacked = vstack(a.clone(), b.clone());
    assert_eq!(stacked.len(), 2);
    assert_eq!(stacked[0], a);
    assert_eq!(stacked[1], b);

    let outer = make_outer(a, b);
    assert_eq!(outer.len(), 2);
    // outer[0] was the same as the first `a`, outer[1] same as first `b`.
    println!("vstack result: {:?}", stacked);
    println!("make_outer result: {:?}", outer);
}